  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Build mutual reachability edges
    edges = []
    for a, b, d in distances:
        w = max(core_dist[a], core_dist[b], d)
        # canonicalize order: smaller string first
        if a < b:
            edges.append((w, a, b))
        else:
            edges.append((w, b, a))

    # Sort by weight, then by node IDs (lexicographic)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)
    for w, a, b in edges:
        if len(mst_edges) == n - 1:
            break
        if union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w

    # Disconnected graph guard (should not happen for valid input)
    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected, cannot build MST")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
}
